import{z as i,x as n,o as A,c as o,q as e,j as r,D as a,d as B,s,S as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"自博弈的奖励塑形","description":"","frontmatter":{"title":"自博弈的奖励塑形","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-reward-shaping.md","filePath":"llm/sgt-reward-shaping.md","lastUpdated":1791413859000}'),d={name:"llm/sgt-reward-shaping.md"};function C(p,E,h,m,D,F){const l=n("Mermaid");return A(),o("div",null,[E[2]||(E[2]=e('<h1 id="自博弈的奖励塑形" tabindex="-1">自博弈的奖励塑形 <a class="header-anchor" href="#自博弈的奖励塑形" aria-label="Permalink to &quot;自博弈的奖励塑形&quot;">​</a></h1><div class="epigraph"><p>塑形是把稀疏的真信号调成稠密的可学信号：调好了只是快慢问题，调歪了连终点都会被搬走。</p><footer>—— 据 Ng, Harada &amp; Russell, Policy Invariance under Reward Transformations, 1999 整理</footer></div><p><a href="/llm/sgt-chess-poker-lessons">上一课</a>的四条教训里最硬的一条是：棋牌自博弈的成功以「外生胜负判据」为前提，而语言任务没有。本课处理由此产生的第一个补丁——奖励塑形：自博弈的原始信号（赢、说服、达成目标）太稀疏或太贵时，怎么造中间信号；以及塑形在博弈环境里多出来的一个单智能体没有的失败模式——<strong>塑形改变均衡</strong>。主干课的<a href="/llm/reward-hacking-llm">奖励黑客</a>讲的是模型骗判据，本课讲的是塑形者自己把博弈改了形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言自博弈的原始奖励常是三样之一：一场辩论谁被裁判选中、一次生成的答案对不对、一次谈判分到多少。三者共同的问题是<strong>方差大、频次低</strong>：一局只有终局信号，千言万语共享一个 0/1。单智能体 RL 的标准解是塑形——给中间步骤发奖励。Ng、Harada 与 Russell 1999 给出安全塑形的经典形式：在原奖励上叠加势函数之差 \\(F(s,s&#39;)=\\gamma\\Phi(s&#39;)-\\Phi(s)\\)，并证明只要 \\(\\Phi\\) 在终止态归零，最优策略不变——塑形只改路径上的梯度景观，不改山顶。</p><p><span class="marginnote">「势函数塑形」可以想象成在登山路上沿途插小旗：山顶不变，但每靠近一面旗就有小奖，让模型不必等到登顶才知道方向对不对。Ng 等人的定理说的是：只要旗子插法合规（终止处归零），插旗不会改变哪里是山顶——注意这是单人在固定山路上的结论。</span></p><p>博弈环境把这个保证的前提抽掉了。势函数塑形的安全性证明是对「固定 MDP」说的；自博弈的 MDP 里有一项由对手策略填的参数，而对手也在被同一个塑形后的奖励训练。于是出现两类单智能体没有的失真：其一，塑形项本身成为双方共同的目标，两个模型可能合力优化塑形代理而不是原博弈——比如都学会产出裁判爱看的长篇，真正的说服力反而无关；其二，塑形造成的目标漂移是<strong>双向的</strong>：你的对手分布随塑形改变，你的最优策略随之改变，终点不再是原博弈的任何均衡。</p><h3 id="语言自博弈的三种塑形" tabindex="-1">语言自博弈的三种塑形 <a class="header-anchor" href="#语言自博弈的三种塑形" aria-label="Permalink to &quot;语言自博弈的三种塑形&quot;">​</a></h3><p>实务上的三种塑形各有形变风险。比较器塑形：SPIN（Chen 等 2024）用「区分自身生成与人类数据」当偏好信号，每轮把上轮生成打成负例——信号稠密，但「对手」恰好是上一轮的自己，塑形定义了一部缓坡梯，且从不保证坡顶是任何博弈的均衡。结果塑形：可验证任务（数学、代码）保留外生判据，塑形只加过程分（主干<a href="/llm/outcome-reward-model">结果奖励模型</a>的做法），这是最接近棋牌条件的配置。裁判塑形：用奖励模型或 LLM 裁判给每局打分，信号最稠密，但判据成了博弈的一部分——双方共同学习裁判的口味，主干课的<a href="/llm/self-reward-debate">self-rewarding 循环依赖</a>记录的正是这个回路的失真。</p><p><span class="marginnote">Ng 等 1999 的定理常被读成「塑形无害」，其前提是势函数在终止处为零且 MDP 固定。自博弈两条都不满足：终止判据可协商，MDP 里有对手这个活动参数——定理不可引用，只能借其形式。</span></p>',10)),(A(),r(t,null,{default:a(()=>[s(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E7%A8%80%E7%96%8F%E7%BB%88%E5%B1%80%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20SHAPE%7B%22%E5%A1%91%E5%BD%A2%E9%80%9A%E9%81%93%22%7D%0A%20%20SHAPE%20--%3E%7C%22%E5%8A%BF%E5%87%BD%E6%95%B0%20%CE%A6%22%7C%20PB%5B%22%E7%AD%96%E7%95%A5%E4%B8%8D%E5%8F%98%E6%80%A7%E6%9C%89%E4%BF%9D%E8%AF%81%EF%BC%8C%E4%BD%86%E9%9C%80%E5%9B%BA%E5%AE%9A%20MDP%22%5D%0A%20%20SHAPE%20--%3E%7C%22%E6%AF%94%E8%BE%83%E5%99%A8%22%7C%20CMP%5B%22%E8%87%AA%E8%BA%AB%E7%94%9F%E6%88%90%E5%BD%93%E8%B4%9F%E4%BE%8B%EF%BC%9ASPIN%20%E5%BC%8F%22%5D%0A%20%20SHAPE%20--%3E%7C%22%E8%A3%81%E5%88%A4%E6%89%93%E5%88%86%22%7C%20JUD%5B%22%E4%BF%A1%E5%8F%B7%E6%9C%80%E7%A8%A0%E5%AF%86%EF%BC%8C%E5%88%A4%E6%8D%AE%E5%85%A5%E5%B1%80%22%5D%0A%20%20PB%20--%3E%20EQ%5B%22%E7%BB%88%E7%82%B9%EF%BC%9A%E5%8E%9F%E5%8D%9A%E5%BC%88%E5%9D%87%E8%A1%A1%E9%99%84%E8%BF%91%22%5D%0A%20%20CMP%20--%3E%20DR%5B%22%E7%BB%88%E7%82%B9%EF%BC%9A%E5%A1%91%E5%BD%A2%E5%AE%9A%E4%B9%89%E7%9A%84%E7%BC%93%E5%9D%A1%22%5D%0A%20%20JUD%20--%3E%20HACK%5B%22%E7%BB%88%E7%82%B9%EF%BC%9A%E8%A3%81%E5%88%A4%E5%8F%A3%E5%91%B3%EF%BC%8C%E5%85%B1%E8%B0%8B%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>先借定理、再核前提</strong>：以 Ng 等 1999 的势函数塑形为形式锚点，逐条核对它的前提（固定 MDP、终止处归零）在自博弈里哪里失效——对手是被同一奖励训练的活动参数——结论是定理不可引用、只借其形式。三条塑形通道（比较器、可验证结果、裁判）按「稠密度换判据入局风险」排成菜单；控制手段压在 \\(\\lambda\\) 退火与 \\(\\Phi\\) 取外部量上，另留一条关塑形的审计通道。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>塑形在博弈中的机制性后果是<strong>均衡位置移动</strong>。原博弈的均衡是对原效用的定义；叠加塑形项后，双方优化的是 \\(u+\\lambda F\\) 的均衡，\\(\\lambda\\) 一大，新均衡可以离原均衡任意远。这不是理论洁癖：语言自博弈里最常见的「越练越啰嗦」，就是塑形项（裁判偏好详尽、比较器偏好与负例可区分）在均衡里兑换成了长度。控制手段因此都作用在 \\(\\lambda\\) 与 \\(\\Phi\\) 的设计上：塑形权重退火（早期靠塑形找路，后期回归原效用）；\\(\\Phi\\) 尽量取「与原效用单调相关的外部量」（如可验证正确率），少取「裁判主观量」；并保留一条<strong>未塑形的审计通道</strong>——定期让双方回到纯原博弈对打，测塑形是否在改写胜负结构。</p><p>这张图回答的问题是：均衡怎么被 \\(\\lambda\\) 和 \\(\\Phi\\) 搬走，三个控制手段各卡在哪一环。</p>',5)),(A(),r(t,null,{default:a(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E5%8E%9F%E6%95%88%E7%94%A8%20u%22%5D%20--%3E%20MIX%5B%22%E5%8F%8C%E6%96%B9%E5%AE%9E%E9%99%85%E4%BC%98%E5%8C%96%EF%BC%9Au%20%2B%20%CE%BBF%22%5D%0A%20%20F%5B%22%E5%A1%91%E5%BD%A2%E9%A1%B9%20F%EF%BC%9A%E7%94%B1%20%CE%A6%20%E4%B8%8E%E5%88%A4%E6%8D%AE%E5%86%B3%E5%AE%9A%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20HOW%7B%22%CE%BB%20%E5%8F%96%E5%A4%9A%E5%A4%A7%22%7D%0A%20%20HOW%20--%3E%7C%22%E5%B0%8F%22%7C%20NEAR%5B%22%E5%9D%87%E8%A1%A1%E5%9C%A8%E5%8E%9F%E5%8D%9A%E5%BC%88%E9%99%84%E8%BF%91%22%5D%0A%20%20HOW%20--%3E%7C%22%E5%A4%A7%22%7C%20FAR%5B%22%E5%9D%87%E8%A1%A1%E8%A2%AB%E6%90%AC%E8%B5%B0%EF%BC%9A%E8%B6%8A%E7%BB%83%E8%B6%8A%E5%95%B0%E5%97%A6%22%5D%0A%20%20FAR%20--%3E%20C1%5B%22%E6%8E%A7%E5%88%B6%E4%B8%80%EF%BC%9A%CE%BB%20%E9%80%80%E7%81%AB%EF%BC%8C%E5%90%8E%E6%9C%9F%E5%9B%9E%E5%BD%92%20u%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%8E%A7%E5%88%B6%E4%BA%8C%EF%BC%9A%CE%A6%20%E5%8F%96%E5%A4%96%E9%83%A8%E9%87%8F%EF%BC%88%E5%8F%AF%E9%AA%8C%E8%AF%81%E6%AD%A3%E7%A1%AE%E7%8E%87%EF%BC%89%22%5D%0A%20%20C2%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E5%AE%9A%E6%9C%9F%E5%85%B3%E5%A1%91%E5%BD%A2%E5%AF%B9%E6%89%93%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>与策略梯度更新器的接口是干净的：塑形只改奖励流，PPO、GRPO 的更新照旧（<a href="/llm/ppo-llm">PPO 实现</a>那一套）。会错在哪：把塑形当无害超参，训练完拿塑形后的指标汇报——那是给改了形的博弈报成绩，不是给原任务。</p><p><span class="marginnote">数字实例：设原效用 = 答对 +1 分，塑形项 = 篇幅每满百字 +0.05。\\(\\lambda=1\\) 时多啰嗦 2000 字才抵一次答对，均衡还认正确率；\\(\\lambda=100\\) 时啰嗦 200 字白赚 10 分，「又长又错」反而成了最优策略——这就是均衡随 \\(\\lambda\\) 搬家的直观版本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>塑形解决「信号稀疏」，不解决「信号错误」：若原效用本身定义错了（判据可被对策），塑形只会让模型更快、更稳地走到错处，这是<a href="/llm/reward-hacking-llm">奖励黑客</a>而非塑形问题，两者要分开诊断——审计时先关塑形再关判据，分别看指标掉多少。</p><p><span class="marginnote">常见误区：把塑形当「无害的辅助超参」，训练完还拿塑形后的指标（裁判评分、长度奖）汇报成绩。那等于给改了形的博弈打分。正确动作是两步关闸：先关塑形、再关判据，各看一次指标掉多少——掉在第一步是塑形病，掉在第二步是判据病。</span> 势函数方法在语言任务里的实操困难是 \\(\\Phi\\) 没有自然候选：状态是对话历史，「势」得人工设计，设计不当的 \\(\\Phi\\) 退化成任意奖励项，定理的庇护随之失效。塑形也只让单局内的学习变稠密，不负责对手分布的广度；信号造好之后，下一课讨论一条更彻底的路——把「胜负」本身设计成一种博弈：辩论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>塑形以势函数差叠加奖励，单智能体下有策略不变性保证；前提是固定 MDP，自博弈不满足。</li><li>博弈环境的独有风险：塑形项成为共同目标，均衡随 \\(\\lambda\\) 与 \\(\\Phi\\) 搬家，「越练越啰嗦」是典型症状。</li><li>三种通道：比较器（SPIN 式）、可验证结果、裁判打分；稠密度与判据入局的风险同向增长。</li><li>控制手段：权重退火、\\(\\Phi\\) 取外部量、保留未塑形审计通道。</li><li>信号错误与信号稀疏要分开诊断：先关塑形、再关判据。</li><li>出处：Ng、Harada 与 Russell 1999；Chen 等 2024（SPIN）。</li></ul>',7))])}const _=i(d,[["render",C]]);export{g as __pageData,_ as default};
